CREATE DATABASE IF NOT EXISTS studenthub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE studenthub; CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, course VARCHAR(80) NOT NULL, year TINYINT UNSIGNED NOT NULL); CREATE TABLE IF NOT EXISTS events (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, event_date DATE NOT NULL, category VARCHAR(80) NOT NULL, description TEXT); CREATE TABLE IF NOT EXISTS registrations (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, event_id INT NOT NULL, registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_registration(student_id,event_id), CONSTRAINT fk_registration_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, CONSTRAINT fk_registration_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE); INSERT IGNORE INTO students(name,email,course,year) VALUES ('Aarav Patel','aarav@example.com','CE',3),('Diya Shah','diya@example.com','IT',2); INSERT IGNORE INTO events(title,event_date,category,description) VALUES ('Orientation Day','2026-11-02','Academic','Student orientation'),('Coding Contest','2026-11-05','Technical','Programming contest'); INSERT IGNORE INTO registrations(student_id,event_id) VALUES (1,1),(2,2);